INSERT INTO repo_sdg_targets (sdg_target_id, target_code, text, status) VALUES ('SDG_TARGET_1_1', '1.1', 'By 2030, eradicate extreme poverty for all people everywhere, currently measured as people living on less than $1.25 a day', 'Active'), ('SDG_TARGET_1_2', '1.2', 'By 2030, reduce at least by half the proportion of men, women and children of all ages living in poverty in all its dimensions according to national definitions', 'Active'), ('SDG_TARGET_1_3', '1.3', 'Implement nationally appropriate social protection systems and measures for all, including floors, and by 2030 achieve substantial coverage of the poor and the vulnerable', 'Active'), ('SDG_TARGET_1_4', '1.4', 'By 2030, ensure that all men and women, in particular the poor and the vulnerable, have equal rights to economic resources, as well as access to basic services, ownership and control over land and other forms of property, inheritance, natural resources, appropriate new technology and financial services, including microfinance', 'Active'), ('SDG_TARGET_1_5', '1.5', 'By 2030, build the resilience of the poor and those in vulnerable situations and reduce their exposure and vulnerability to climate-related extreme events and other economic, social and environmental shocks and disasters', 'Active'), ('SDG_TARGET_1_a', '1.a', 'Ensure significant mobilization of resources from a variety of sources, including through enhanced development cooperation, in order to provide adequate and predictable means for developing countries, in particular least developed countries, to implement programmes and policies to end poverty in all its dimensions', 'Active'), ('SDG_TARGET_1_b', '1.b', 'Create sound policy frameworks at the national, regional and international levels, based on pro-poor and gender-sensitive development strategies, to support accelerated investment in poverty eradication actions', 'Active'), ('SDG_TARGET_2_1', '2.1', 'By 2030, end hunger and ensure access by all people, in particular the poor and people in vulnerable situations, including infants, to safe, nutritious and sufficient food all year round', 'Active'), ('SDG_TARGET_2_2', '2.2', 'By 2030, end all forms of malnutrition, including achieving, by 2025, the internationally agreed targets on stunting and wasting in children under 5 years of age, and address the nutritional needs of adolescent girls, pregnant and lactating women and older persons', 'Active'), ('SDG_TARGET_2_3', '2.3', 'By 2030, double the agricultural productivity and incomes of small-scale food producers, in particular women, indigenous peoples, family farmers, pastoralists and fishers, including through secure and equal access to land, other productive resources and inputs, knowledge, financial services, markets and opportunities for value addition and non-farm employment', 'Active'), ('SDG_TARGET_2_4', '2.4', 'By 2030, ensure sustainable food production systems and implement resilient agricultural practices that increase productivity and production, that help maintain ecosystems, that strengthen capacity for adaptation to climate change, extreme weather, drought, flooding and other disasters and that progressively improve land and soil quality', 'Active'), ('SDG_TARGET_2_5', '2.5', 'By 2020, maintain the genetic diversity of seeds, cultivated plants and farmed and domesticated animals and their related wild species, including through soundly managed and diversified seed and plant banks at the national, regional and international levels, and promote access to and fair and equitable sharing of benefits arising from the utilization of genetic resources and associated traditional knowledge, as internationally agreed', 'Active'), ('SDG_TARGET_2_a', '2.a', 'Increase investment, including through enhanced international cooperation, in rural infrastructure, agricultural research and extension services, technology development and plant and livestock gene banks in order to enhance agricultural productive capacity in developing countries, in particular least developed countries', 'Active'), ('SDG_TARGET_2_b', '2.b', 'Correct and prevent trade restrictions and distortions in world agricultural markets, including through the parallel elimination of all forms of agricultural export subsidies and all export measures with equivalent effect, in accordance with the mandate of the Doha Development Round', 'Active'), ('SDG_TARGET_2_c', '2.c', 'Adopt measures to ensure the proper functioning of food commodity markets and their derivatives and facilitate timely access to market information, including on food reserves, in order to help limit extreme food price volatility', 'Active'), ('SDG_TARGET_3_1', '3.1', 'By 2030, reduce the global maternal mortality ratio to less than 70 per 100,000 live births', 'Active'), ('SDG_TARGET_3_2', '3.2', 'By 2030, end preventable deaths of newborns and children under 5 years of age, with all countries aiming to reduce neonatal mortality to at least as low as 12 per 1,000 live births and under-5 mortality to at least as low as 25 per 1,000 live births', 'Active'), ('SDG_TARGET_3_3', '3.3', 'By 2030, end the epidemics of AIDS, tuberculosis, malaria and neglected tropical diseases and combat hepatitis, water-borne diseases and other communicable diseases', 'Active'), ('SDG_TARGET_3_4', '3.4', 'By 2030, reduce by one third premature mortality from non-communicable diseases through prevention and treatment and promote mental health and well-being', 'Active'), ('SDG_TARGET_3_5', '3.5', 'Strengthen the prevention and treatment of substance abuse, including narcotic drug abuse and harmful use of alcohol', 'Active'), ('SDG_TARGET_3_6', '3.6', 'By 2020, halve the number of global deaths and injuries from road traffic accidents', 'Active'), ('SDG_TARGET_3_7', '3.7', 'By 2030, ensure universal access to sexual and reproductive health-care services, including for family planning, information and education, and the integration of reproductive health into national strategies and programmes', 'Active'), ('SDG_TARGET_3_8', '3.8', 'Achieve universal health coverage, including financial risk protection, access to quality essential health-care services and access to safe, effective, quality and affordable essential medicines and vaccines for all', 'Active'), ('SDG_TARGET_3_9', '3.9', 'By 2030, substantially reduce the number of deaths and illnesses from hazardous chemicals and air, water and soil pollution and contamination', 'Active'), ('SDG_TARGET_3_a', '3.a', 'Strengthen the implementation of the World Health Organization Framework Convention on Tobacco Control in all countries, as appropriate', 'Active'), ('SDG_TARGET_3_b', '3.b', 'Support the research and development of vaccines and medicines for the communicable and non-communicable diseases that primarily affect developing countries, provide access to affordable essential medicines and vaccines, in accordance with the Doha Declaration on the TRIPS Agreement and Public Health, which affirms the right of developing countries to use to the full the provisions in the Agreement on Trade-Related Aspects of Intellectual Property Rights regarding flexibilities to protect public health, and, in particular, provide access to medicines for all', 'Active'), ('SDG_TARGET_3_c', '3.c', 'Substantially increase health financing and the recruitment, development, training and retention of the health workforce in developing countries, especially in least developed countries and small island developing States', 'Active'), ('SDG_TARGET_3_d', '3.d', 'Strengthen the capacity of all countries, in particular developing countries, for early warning, risk reduction and management of national and global health risks', 'Active'), ('SDG_TARGET_4_1', '4.1', 'By 2030, ensure that all girls and boys complete free, equitable and quality primary and secondary education leading to relevant and effective learning outcomes', 'Active'), ('SDG_TARGET_4_2', '4.2', 'By 2030, ensure that all girls and boys have access to quality early childhood development, care and pre-primary education so that they are ready for primary education', 'Active'), ('SDG_TARGET_4_3', '4.3', 'By 2030, ensure equal access for all women and men to affordable and quality technical, vocational and tertiary education, including university', 'Active'), ('SDG_TARGET_4_4', '4.4', 'By 2030, substantially increase the number of youth and adults who have relevant skills, including technical and vocational skills, for employment, decent jobs and entrepreneurship', 'Active'), ('SDG_TARGET_4_5', '4.5', 'By 2030, eliminate gender disparities in education and ensure equal access to all levels of education and vocational training for the vulnerable, including persons with disabilities, indigenous peoples and children in vulnerable situations', 'Active'), ('SDG_TARGET_4_6', '4.6', 'By 2030, ensure that all youth and a substantial proportion of adults, both men and women, achieve literacy and numeracy', 'Active'), ('SDG_TARGET_4_7', '4.7', 'By 2030, ensure that all learners acquire the knowledge and skills needed to promote sustainable development, including, among others, through education for sustainable development and sustainable lifestyles, human rights, gender equality, promotion of a culture of peace and non-violence, global citizenship and appreciation of cultural diversity and of culture’s contribution to sustainable development', 'Active'), ('SDG_TARGET_4_a', '4.a', 'Build and upgrade education facilities that are child, disability and gender sensitive and provide safe, non-violent, inclusive and effective learning environments for all', 'Active'), ('SDG_TARGET_4_b', '4.b', 'By 2020, substantially expand globally the number of scholarships available to developing countries, in particular least developed countries, small island developing States and African countries, for enrolment in higher education, including vocational training and information and communications technology, technical, engineering and scientific programmes, in developed countries and other developing countries', 'Active'), ('SDG_TARGET_4_c', '4.c', 'By 2030, substantially increase the supply of qualified teachers, including through international cooperation for teacher training in developing countries, especially least developed countries and small island developing States', 'Active'), ('SDG_TARGET_5_1', '5.1', 'End all forms of discrimination against all women and girls everywhere', 'Active'), ('SDG_TARGET_5_2', '5.2', 'Eliminate all forms of violence against all women and girls in the public and private spheres, including trafficking and sexual and other types of exploitation', 'Active'), ('SDG_TARGET_5_3', '5.3', 'Eliminate all harmful practices, such as child, early and forced marriage and female genital mutilation', 'Active'), ('SDG_TARGET_5_4', '5.4', 'Recognize and value unpaid care and domestic work through the provision of public services, infrastructure and social protection policies and the promotion of shared responsibility within the household and the family as nationally appropriate', 'Active'), ('SDG_TARGET_5_5', '5.5', 'Ensure women’s full and effective participation and equal opportunities for leadership at all levels of decision-making in political, economic and public life', 'Active'), ('SDG_TARGET_5_6', '5.6', 'Ensure universal access to sexual and reproductive health and reproductive rights as agreed in accordance with the Programme of Action of the International Conference on Population and Development and the Beijing Platform for Action and the outcome documents of their review conferences', 'Active'), ('SDG_TARGET_5_a', '5.a', 'Undertake reforms to give women equal rights to economic resources, as well as access to ownership and control over land and other forms of property, financial services, inheritance and natural resources, in accordance with national laws', 'Active'), ('SDG_TARGET_5_b', '5.b', 'Enhance the use of enabling technology, in particular information and communications technology, to promote the empowerment of women', 'Active'), ('SDG_TARGET_5_c', '5.c', 'Adopt and strengthen sound policies and enforceable legislation for the promotion of gender equality and the empowerment of all women and girls at all levels', 'Active'), ('SDG_TARGET_6_1', '6.1', 'By 2030, achieve universal and equitable access to safe and affordable drinking water for all', 'Active'), ('SDG_TARGET_6_2', '6.2', 'By 2030, achieve access to adequate and equitable sanitation and hygiene for all and end open defecation, paying special attention to the needs of women and girls and those in vulnerable situations', 'Active'), ('SDG_TARGET_6_3', '6.3', 'By 2030, improve water quality by reducing pollution, eliminating dumping and minimizing release of hazardous chemicals and materials, halving the proportion of untreated wastewater and substantially increasing recycling and safe reuse globally', 'Active') ON CONFLICT DO NOTHING;